find_rule:
js:
var d = [];
var html = request(input);
var items = pdfa(html, ".module-items&&.module-item");
for (var i = 0; i < items.length; i++) {
  var item = items[i];
  var title = pdfh(item, ".module-item-title&&Text");
  var img = pd(item, ".module-item-pic img&&data-original||.module-item-pic img&&src", input);
  var url = pd(item, ".module-item-title&&href", input);
  var desc = pdfh(item, ".module-item-note&&Text");
  d.push({
    title: title,
    desc: desc,
    pic_url: img + '@Referer=' + input,
    url: url,
    col_type: 'movie_3'
  });
}
setResult(d);

