detail_find_rule:
js:
var d = [];
var html = request(input);
var title = pdfh(html, ".video-info-header h1&&Text");
var cover = pd(html, ".video-cover img&&src", input);
var intro = pdfh(html, ".video-info-main&&Text");

// 1. 顶部基础卡片
d.push({
  title: title,
  desc: intro,
  pic_url: cover + '@Referer=' + input,
  url: input,
  col_type: 'pic_1_card'
});

// 2. 线路 Tab 提取
var tabs = pdfa(html, ".module-tab-items-box&&.module-tab-item");
var playlists = pdfa(html, ".module-list&&.module-blocklist");

for (var tabIndex = 0; tabIndex < tabs.length; tabIndex++) {
  var tabName = pdfh(tabs[tabIndex], "Text") || ('线路 ' + (tabIndex + 1));
  d.push({
    title: '【' + tabName + '】',
    col_type: 'text_1'
  });
  var currentList = playlists[tabIndex] ? pdfa(playlists[tabIndex], "a") : [];
  for (var epIndex = 0; epIndex < currentList.length; epIndex++) {
    var ep = currentList[epIndex];
    var epTitle = pdfh(ep, "Text");
    var epUrl = pd(ep, "a&&href", input);
    d.push({
      title: epTitle,
      url: 'lazy:' + epUrl,
      col_type: 'text_3'
    });
  }
}
setResult(d);

lazy:
js:
var html = request(input);
var realPlayUrl = '';
// 示例：从网页播放器配置或内联 iframe 提取真实媒体地址
var match = html.match(/player_aaaa\s*=\s*({[\s\S]*?})<\/script>/);
if (match && match[1]) {
  var config = JSON.parse(match[1]);
  if (config.url) {
    realPlayUrl = config.url;
    if (realPlayUrl.indexOf('http') !== 0) {
      realPlayUrl = 'https:' + realPlayUrl;
    }
  }
}
if (!realPlayUrl) {
  realPlayUrl = input;
}
// 注入标准防盗链头
realPlayUrl = realPlayUrl + ';{Referer@' + input + '&&User-Agent@PC}';
setResult({ url: realPlayUrl });
